      if (!_cards.some(c => c.k === _k)) _cards.push({ k: _k, ct: _ct });
    }
  }
  if (_lastOk && _cards.length) {
    text = _cards[0].ct; _prepared = true;
    if (_cards.length > 1) {
      const _q = _cards.slice(1).map(c => {
        const _ti = ((c.ct.split('\n').find(l => /^\*[^*\n]+\*$/.test(l.trim())) || '').trim().replace(/^\*|\*$/g, ''));
        const _dt = ((c.ct.match(/^\*Date:\*\s*([^\n]+)$/m) || [])[1] || '').trim();
        return _ti && _dt ? "_Next: " + _ti + " on " + _dt + " - I'll show it after this one._" : '';
      }).filter(Boolean);
      if (_q.length) text = /_check [0-9a-f]{8}_/.test(text) ? text.replace(/(_check [0-9a-f]{8}_)/, '$1\n' + _q.join('\n'))
        : text.replace(/\n*(?:Reply only with "yes" to cancel[^\n]*\n)?\s*Confirm to cancel\.\s*$/i, '\n' + _q.join('\n') + '\n\nConfirm to cancel.');   // v204: no code on the short card
    }
  }
} catch (e) {}

// --- v189: the move card IS the reply -------------------------------------------------------------------------------
// Move Booking v25 checks the booking before asking for the yes and writes the card itself - where it is now and where it
// is going - so the requester sees both before approving. Same rule as a cancel card: the latest Move Booking call this
// turn decides, and nothing below may change it.
try {
  const _s2 = (($input.first().json || {}).intermediateSteps) || [];
  for (let i = _s2.length - 1; i >= 0; i--) {
    const _t = String(((_s2[i] || {}).action || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
    if (_t !== 'move booking') continue;
    let _o = null; try { _o = [].concat(JSON.parse(String((_s2[i] || {}).observation || '')))[0]; } catch (e) {}
    if (_o && _o.reason === 'NOT_CONFIRMED' && _o.card_text) { text = String(_o.card_text); _prepared = true; }
    break;
  }
} catch (e) {}

// --- v168 (live, 28 Sep): they said no, and the same summary went out again -----------------------------------
// Gate Context told the model "THEY SAID NO ... do not show that same summary again unchanged"; it called Prepare
// Booking with the same details and the refused summary was re-sent word for word. A prepared summary whose check
// code is the one they just refused is replaced by the question the notice asked for.
try {
  const _dn = String((($('Gate Context').first() || {}).json || {}).declineNotice || '');
  if (_prepared && _dn) {
    const _code = (text.match(/_check ([0-9a-f]{6,})_/) || [])[1];
    const _bt = String((($('Booked For').first() || {}).json || {}).botText || '');
    // v203: the short summary has no code - the same summary is its title, Date, Time and Room block again
    const _core = text.split(/\n\s*\n/)[0].trim();
    if ((_code && _bt.indexOf('_check ' + _code + '_') !== -1) || (!_code && _core.length > 20 && _bt.indexOf(_core) !== -1)) {
      text = 'No problem - nothing was booked. What would you like to change?';
      _prepared = false;
    }
  }
} catch (e) {}

// Slack mrkdwn uses single asterisks. The model emits ** despite the prompt
// forbidding it, and Slack shows those as literal characters. Fixed here rather
// than asked for again.
text = text.replace(/\*{2,}/g, '*');

// --- the confirmation marker, normalised ---------------------------------
// Gate Context matches the marker at the end of the message, so anything she
// adds to it breaks the gate. On 2026-08-30 she wrote "Confirm to cancel both.
// (y/n)" and the cancellation was refused as NOT_CONFIRMED - safe, but two
// wasted turns, and she rephrases constantly. The gate stays strict; the line
// is put back into its canonical form here instead.
text = text.replace(
  /(?:Reply only with "yes"[^\n]*\n)?Confirm to (book|cancel|move)\b[^.\n!?]{0,40}([.!]?)(\s*\((?:y\/n|yes\/no)\))?\s*$/i,
  (whole, verb) => {
    const v = verb.toLowerCase();
    const neg = v === 'cancel' ? 'keep it' : (v === 'move' ? 'keep it where it is' : 'change anything');
    return 'Reply only with "yes" to ' + v + ', or "no" to ' + neg + '.\nConfirm to ' + v + '.';
  });

// --- vocabulary the requester should never see ---------------------------
// "Priority" and "Last Resort" are Airtable column names. Tara, 2026-08-30:
// "just dont mention priority and last resort" - "last resort" makes a
// preference sound like a rule. v92 said so in the prompt and the words still
// appeared in five replies, so it is done here instead, where compliance is
// not required.
// Each pattern swallows the article in front of it, or the replacement lands
// inside the old one - "The the rooms normally used", "is a a room normally
// used". Longest phrases first.
const SAY = [
  [/\b(these|those)\s+priority rooms\b/gi,      '$1 rooms'],
  [/\b(the)\s+priority rooms\b/gi,             '$1 rooms normally used'],
  [/\b(a|an)\s+priority room\b/gi,              'a room normally used'],
  [/\bpriority rooms\b/gi,                      'rooms normally used'],
  [/\bpriority room\b/gi,                       'room normally used'],
  [/\b(a|an)\s+last[- ]resort room\b/gi,        'not one of the usual rooms'],
  [/\b(these|those|the)\s+last[- ]resort rooms\b/gi, '$1 other rooms'],
  [/\blast[- ]resort rooms\b/gi,                'other rooms'],
  [/\blast[- ]resort room\b/gi,                 'another room'],
  [/\b(a|an)\s+last[- ]resort choice\b/gi,      'not the usual choice'],
  [/\blast[- ]resort choice\b/gi,               'not the usual choice'],
  [/\bas a last resort\b/gi,                    'if nothing else is free'],
  [/\bprioriti[sz]ed\b/gi,                      'normally used'],
  // v162: anything the patterns above missed ("a last-resort or alternative room", eval 2026-09-27 DATE-5).
  [/\b(a|an)\s+last[- ]resort\b/gi,              'a backup'],
  [/\blast[- ]resort\b/gi,                       'backup']
];
for (const [re, to] of SAY) text = text.replace(re, to);

// --- the weekday she prints beside a date --------------------------------
// Gate Context resolves the date and states the weekday, and she has still
// written "September 9, 2027 (Wed)" for a Thursday three times - twice in a
// booking summary, which is the line a requester scans before saying yes. The
// date is the fact; the weekday is derived from it, so it is corrected here
// rather than trusted.
const DAYS  = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const MONTHS = { january:0, february:1, march:2, april:3, may:4, june:5, july:6,
                 august:7, september:8, october:9, november:10, december:11 };
const dayOf = (y, m, d) => new Date(Date.UTC(y, m, d)).getUTCDay();

// "September 9, 2027 (Wed)" / "9 September 2027 (Wed)"
// The whole parenthesised word is captured, not just its three-letter prefix.
// The old form captured only the abbreviation and swapped that, so a wrong long
// day name became a mangled one: "(Wednesday)" for a Thursday had "Wed" replaced
// with "Thu" and kept the tail, printing "(Thunesday)" in a booking summary on
// 2026-09-03. That then read like the model corrupting a string, when it was this
// correction doing it. Long form in, long form out; short in, short out - and a
// value already mangled by the old code is repaired, since it still starts with a
// real abbreviation.
text = text.replace(
  /\b([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})\s*\(((?:Sun|Mon|Tue|Wed|Thu|Fri|Sat)[a-z]*)\)/g,
  (whole, mon, d, y, written) => {
    const m = MONTHS[String(mon).toLowerCase()];
    if (m === undefined) return whole;
    const idx = dayOf(+y, m, +d);
    const right = written.length > 3 ? DAYS[idx] : SHORT[idx];
    return written === right ? whole : whole.replace('(' + written + ')', '(' + right + ')');
  });

// "Wednesday, September 9, 2027"
text = text.replace(
  /\b(Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday),\s+([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})/g,
  (whole, named, mon, d, y) => {
    const m = MONTHS[String(mon).toLowerCase()];
    if (m === undefined) return whole;
    const right = DAYS[dayOf(+y, m, +d)];
    return right === named ? whole : right + whole.slice(named.length);
  });

// --- internal vocabulary that leaked during QA ---------------------------
// "deviation" is how the room ranking is described internally. A requester
// reading "Room: Studio 5 (deviation: another room for post mixing)" is being
// shown a schema, not an explanation - the same complaint Tara made about
// "priority" and "last resort" on 2026-08-30. "BLOCKED - " is the prefix the
// guards use to make a refusal unmissable to the model; it is not for a person.
text = text.replace(/^\s*BLOCKED\s*[-\u2013\u2014:]\s*/i, '');
// Each pattern swallows the article in front of it. v100 replaced the noun
// alone and shipped "Studio 3 is a exception for VO Recording" - the same
// mistake the priority/last-resort list above already carries a warning about.
const DEV = [
  [/\bis\s+an?\s+deviation\s+from\s+the\s+usual\s+rooms?\b/gi, 'is not one of the usual rooms'],
  [/\ban?\s+deviation\s+from\b/gi, 'different from'],
  [/\bis\s+an?\s+deviations?\b/gi, 'is not a usual room'],
  [/\ban?\s+deviations?\b/gi,       'an exception'],
  [/\(\s*deviations?:\s*/gi,        '('],
  [/\bdeviations?:\s*/gi,            'note: '],
  [/\bdeviations?\b/gi,              'exception']
];
for (const [re, to] of DEV) text = text.replace(re, to);

// --- the label on the booker line ----------------------------------------
// Every summary says "Booked by:" except when it says "Booking Owner:".
text = text.replace(/\*\s*Booking Owner\s*:\s*\*/gi, '*Booked by:*');
// She also drops the space - "*Bookedby:* Tara Lim" on 2026-08-30. Both
// forms are normalised here, before the name repair below, or that repair
// does not match the line it is meant to fix.
text = text.replace(/\*\s*Bookedby\s*:\s*\*/gi, '*Booked by:*');

// --- the prompt's own numbering ------------------------------------------
// "since rule 1 says we never move or cancel an existing booking to clear a
// room" went out on 2026-09-01. The rules are numbered for the model's benefit;
// a requester has no rule 1 and hearing about one makes a studio policy sound
// like a software constraint. The substance is kept, the citation dropped.
// Removing the citation can leave the sentence starting lowercase. v115 shipped
// "Rule 1 says we never delete..." -> "we never delete...", mid-paragraph and
// uncapitalised. So the sentence-initial form carries the following letter into
// the match and puts it back in upper case; the mid-sentence form does not need
// to, because the connector before it survives.
text = text.replace(
  /(^|[\n.!?]\s*)rule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?([a-z])/gi,
  (whole, pre, ch) => pre + ch.toUpperCase());
const CITE = [
  [/\b(since|because|as)\s+rule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?/gi, '$1 '],
  [/\b(?:per|under|by)\s+rule\s+\d+\s*,?\s*/gi, ''],
  [/\brule\s+\d+\s+(?:says|states|requires)\s+(?:that\s+)?/gi, ''],
  [/\b(?:the\s+)?(?:three\s+)?unoverridable\s+rules?\b/gi, 'the booking rules'],
  // Singular, because what follows is a singular verb: "rule 1 is absolute"
  // became "the booking rules is absolute". Third grammar break from this
  // family of rewrites - the article one, the capitalisation one, then
  // agreement. A regex cannot promise the result reads correctly, so the sweep
  // below catches the disagreement these rewrites can leave behind.
  [/\brule\s+\d+\b/gi, 'a standing rule']
];
for (const [re, to] of CITE) text = text.replace(re, to);
text = text.replace(/\brules\s+is\b/gi, 'rules are')
           .replace(/\ba\s+standing\s+rule\s+are\b/gi, 'a standing rule is');

// --- what the tools actually returned this turn --------------------------
// intermediateSteps arrive on this node's input, so reading them costs nothing
// and hangs nothing (gotcha 11). Extracted up here because two blocks below
// need the evidence, not just the claim check that came first.
let steps = null;
try {
  const st = $input.first().json.intermediateSteps;
  if (Array.isArray(st)) steps = st;
} catch (e) {}

// Everything a tool returned or was handed this turn, as one lowercase string.
// A name or title found in here was reported by a tool and is not the model's
// invention, whatever else is wrong with the sentence around it.
let evidence = '';
try {
  for (const st of (steps || [])) {
    evidence += ' ' + JSON.stringify(((st || {}).action || {}).toolInput || '');
    evidence += ' ' + String((st || {}).observation || '');
  }
  evidence = evidence.replace(/\s+/g, ' ').toLowerCase();
} catch (e) { evidence = ''; }

// Edit distance, capped - only ever asked about short names.
const editDist = (a, b) => {
  a = String(a); b = String(b);
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = [];
  for (let j = 0; j <= b.length; j++) prev[j] = j;
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1,
                        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
};

// --- who actually booked it ----------------------------------------------
// The model retypes the booker's name and has corrupted it: "Tara Lim" came
// back "Tara Inf" on 2026-08-30, in the line a requester scans before saying
// yes. The name is known from Airtable, so it is written rather than trusted.
// The calendar entry was never at risk - its "Booked by" comes from Get Booker
// through a workflow input, and the model never supplies it.
//
// It is NOT always the requester. A cancel or a lookup shows someone else's
// booking, and until v119 this block relabelled it: asked to cancel a booking
// held by another engineer on 2026-09-03, Find Booking returned the real owner
// and this line replaced their name with the requester's - turning the refusal
// that follows ("that is not yours") into a contradiction of the summary right
// above it, in the one context where the name is the whole point.
//
// So it only overwrites a name that is BOTH absent from what the tools returned
// this turn and a near-miss of the real one. A corruption is neither reported
// nor plausible; a third party's name is reported, and is nobody's typo.
try {
  const realBooker = String($('Get Booker').first().json.fields.Name || '').trim();
  if (realBooker && !_prepared) {   // v163: a prepared Booked by line came from Get Booker itself
    const target = realBooker.toLowerCase();
    text = text.replace(/(\*Booked by:\*[ \t]*)([^\n*]+)/g, (whole, lead, got) => {
      const name = got.trim();
      if (!name || name === realBooker) return whole;
      // reported by a tool this turn - not the model's to be corrected
      if (evidence && evidence.indexOf(name.toLowerCase()) !== -1) return whole;
      // a corruption stays close to the original; a different person does not
      const d = editDist(name.toLowerCase(), target);
      if (d > Math.max(2, Math.floor(target.length * 0.4))) return whole;
      return lead + realBooker;
    });
  }
} catch (e) {}

// --- a date written without a year --------------------------------------
// Both corrections above need a four-digit year. She also writes "next
// Wednesday, September 9" with no year, and that form went out uncorrected for
// a Thursday on 2026-08-30. The year comes from the date Gate Context already
// resolved rather than from a second copy of the QA year shift; with no year to
// work from the line is left alone.
//
// The day number needs (?!\d) as well as the year lookahead. Without it
// `\d{1,2}` backtracks: on "Friday, September 10, 2027" the lookahead rejects
// d=10, the engine retries with d=1, the lookahead passes, and the line is
// rewritten to the weekday of September *1st*. Every dated weekday with a
// two-digit day came out wrong from v104 to v118, and it silently undid the
// dated correction 60 lines above - which is how it hid: on 2026-09-03
// "next Wednesday, September 10, 2027" was corrected to Friday and then put
// back to Wednesday, so the block above looked like it was doing nothing.
// Only prose lines carry this form; summaries write "September 10, 2027 (Fri)"
// and go through the abbreviation block instead, which is why nobody saw it.
//
// This is the only node lookup added in v104. v102 added three at once and
// Guard Probe began timing out at 60s on every message, so they go back one at
// a time and each one is checked against a real execution before the next.
let refYear = null;
try {
  const gc = $('Gate Context').first().json;
  const ym = (String(gc.dateNotice || '') + ' ' + String(gc.pastDateNotice || '')).match(/\b(20\d{2})\b/);
  if (ym) refYear = +ym[1];
} catch (e) {}
if (refYear) {
  text = text.replace(
    /\b(Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday),\s+([A-Za-z]+)\s+(\d{1,2})(?!\d)(?!\s*,?\s*\d{4})/g,
    (whole, named, mon, d) => {
      const m = MONTHS[String(mon).toLowerCase()];
      if (m === undefined) return whole;
      const right = DAYS[dayOf(refYear, m, +d)];
      return right === named ? whole : right + whole.slice(named.length);
    });
}

// --- a duration nobody asked for ----------------------------------------
// Gate Context spots a start time with no end and tells her to say what length
// she is assuming. She did it once on 2026-08-30 and ignored it the next time,
// which is what an instruction in the prompt is worth. Written here when the
// summary does not already say it.
//
// Uses the same $('Gate Context') lookup as the weekday correction above - v105
// adds no new one. Guard Probe ran 70ms with that lookup in v104.
try {
  const startOnly = String($('Gate Context').first().json.startOnlyNotice || '').length > 0;
  if (startOnly && /Confirm to book\./i.test(text) && !/\bassum/i.test(text)) {
    const t = text.match(/\*Time:\*\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)\s*[-\u2013\u2014]\s*(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
    if (t) {
      const to24 = (h, ap) => (String(ap).toUpperCase() === 'PM' ? (+h % 12) + 12 : (+h % 12));
      const mins = (to24(t[4], t[6]) * 60 + (+t[5] || 0)) - (to24(t[1], t[3]) * 60 + (+t[2] || 0));
      if (mins > 0) {
        const hrs = Math.floor(mins / 60), rem = mins % 60;
        const len = (hrs ? hrs + ' hour' + (hrs === 1 ? '' : 's') : '')
                  + (hrs && rem ? ' ' : '') + (rem ? rem + ' minutes' : '');
        text = 'Assumed ' + len + '.\n\n' + text;
      }
    }
  }
} catch (e) {}

// --- v187 (QA bug 15): a start time only, and the reply shows an end nobody gave -----------------------------------
// "is studio 7 free next thursday at 2pm?" -> "free ... from 2:00 PM to 4:00 PM" (exec 15881): Room Availability was
// asked about a 2-hour window and the model reported the window as if it had been asked for. An availability line that
// runs from the requester's start to a time they never typed says "at 2:00 PM (checked until 4:00 PM)" instead.
// Someone else's booking ("taken from 1:00 PM to 3:00 PM") is a real time and is never touched.
try {
  const _so = String($('Gate Context').first().json.startOnlyNotice || '').length > 0;
  if (_so && !_prepared && !/Confirm to (book|cancel|move)\./i.test(text) && !/\*Time:\*/.test(text)) {
    let _said = '';
    try { _said = String($('Slack Trigger').first().json.text || ''); } catch (e) {}
    try { _said += '\n' + String((($('Booked For').first() || {}).json || {}).requesterText || ''); } catch (e) {}
    const _typed = x => {
      const m = String(x).match(/(\d{1,2})(?::(\d{2}))?\s*([AP])M/i); if (!m) return true;
      const mm = m[2] && m[2] !== '00' ? ':' + m[2] : '(?::00)?';
      return new RegExp('(^|[^0-9:])' + (+m[1]) + mm + '\\s*' + m[3] + '\\.?\\s*m\\b', 'i').test(_said)
        || (m[3].toUpperCase() === 'P' && +m[1] === 12 && (!m[2] || m[2] === '00') && /\b(?:12\s*nn|noon)\b/i.test(_said));
    };
    let _chg = false;
    text = text.split('\n').map(l => {
      if (!/\b(free|available|open)\b/i.test(l) || /\b(taken|busy|booked by|occupied)\b/i.test(l)) return l;
      return l.replace(/\b(?:from\s+)?(\d{1,2}:\d{2}\s*[AP]M)\s*(?:to|until|till|-|–|—)\s*(\d{1,2}:\d{2}\s*[AP]M)/gi, (w, s, e) => {
        if (!_typed(s) || _typed(e)) return w;
        _chg = true; return 'at ' + s + ' (checked until ' + e + ')';
      });
    }).join('\n');
    if (_chg && !/\?/.test(text)) text = text.trim() + '\n\nHow long do you need it?';
  }
} catch (e) {}

// --- a note that contradicts the ranking ---------------------------------
// "Studio 7 is outside the usual rooms for Post Mixing (Studio 7 and 8 are the
// usual rooms for Post Mixing, so Studio 7 is one of the usual rooms)" went out
// on 2026-08-30. Studio 7 is first in that ranking; the note had carried over
// from an earlier turn about Studio 3. The ranking is known here, so a note the
// ranking contradicts is removed rather than sent.
//
// $('Room Table') is the last of the three lookups v102 added and the only one
// still unaccounted for - Gate Context was cleared at 70ms in v104. It ships on
// its own so the next execution's timing says plainly whether this is what hung
// Guard Probe for 60s.
try {
  const table = String($('Room Table').first().json.roomTable || '');
  const esc = s => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  text = text.replace(/^[ \t]*\*Note:\*[^\n]*\n?/gim, line => {
    const m = line.match(/\*Note:\*\s*(.+?)\s+is\s+(?:outside|not one of|not a)\b[^\n]*?\bfor\s+([A-Za-z0-9 ]+?)\s*[.,(]/i);
    if (!m) return line;
    const room = m[1].trim(), type = m[2].trim();
    const row = table.split('\n').find(r => new RegExp('^-\\s*' + esc(type) + '\\s+\u2014', 'i').test(r.trim()));
    if (!row) return line;
    return new RegExp('\\b' + esc(room) + '\\b', 'i').test(row) ? '' : line;
  });
} catch (e) {}

// --- a claim with nothing behind it --------------------------------------
// On 2026-08-30 she answered an approved booking with "Booked. That is a bit
// shorter than VO Recording sessions usually run" without calling Book Session
// at all, copying an almost identical exchange from two turns earlier. Nothing
// reached the calendar and the requester was told it had. One run in 120, and
// the worst sentence this bot can produce: every other guard stops a wrong
// booking being made, none of them stops one being claimed.
//
// The obvious check is unavailable - $('Book Session') hangs the task runner
// for 60s (CLAUDE.md gotcha 11, PENDING 14). This reads the agent's own
// intermediateSteps, which arrive on this node's input, so there is no node
// lookup to hang. It is also a stronger check than asking whether the node ran:
// it requires the tool to have returned a success status on THIS turn.
//
// Conservative by design. If the steps are missing - the agent option off, or an
// older execution - nothing is rewritten and claimProbe says so. Telling someone
// a real booking failed would be worse than the bug this fixes.
let claimProbe = 'no claim';
const CLAIMS = [
  [/^\s*\*?Booked\b|\bhas been booked\b/i, [['book session', ['CREATED']], ['book series', ['BOOKED_SERIES']]], 'booked'],
  [/^\s*\*?Cancell?ed\b/i,                   [['cancel booking', ['CANCELLED']]],                                 'cancelled'],
  [/^\s*\*?Moved\b/i,                        [['move booking',   ['MOVED', 'PARTIAL']]],                          'moved']
];
for (const [re, wanted, word] of CLAIMS) {
  if (!re.test(text)) continue;
  if (!steps) { claimProbe = word + ': no intermediateSteps on input'; break; }
  const ran = steps.some(st => {
    const tool = String((((st || {}).action) || {}).tool || '').replace(/[_\s]+/g, ' ').toLowerCase();
    const obs = String((st || {}).observation || '');
    return wanted.some(pair => tool === pair[0] && pair[1].some(s => obs.indexOf('"' + s + '"') !== -1));
  });
  claimProbe = word + ': ' + (ran ? 'confirmed' : 'NOT FOUND');
  if (!ran) {
    text = 'Sorry \u2014 that did not go through, and I should not have said otherwise. Nothing was '
         + word + '. Say "yes" again and I will retry it.';
  }
  break;
}

