// v194: a compact list of this turn's tool calls, for the Turn Log (Turn Log Row cannot read the agent itself).
let toolsLog = '';
try {
  const _cl = (s, n) => { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '...' : s; };
  const _K = ['title', 'booking_date', 'start', 'end', 'new_start', 'new_end', 'rooms', 'window_start', 'window_end', 'window_room', 'engineer', 'client', 'summary', 'recur_frequency', 'recur_days', 'recur_start', 'recur_count', 'recur_until', 'recur_time_start', 'recur_time_end'];   // v206: series inputs too
  toolsLog = _cl(((($input.first().json || {}).intermediateSteps) || []).map(s => {
    const a = (s && s.action) || {}, ti = a.toolInput || {};
    let o = null; try { o = [].concat(JSON.parse(String(s.observation || '')))[0]; } catch (e) {}
    return (a.tool || '?') + '(' + _K.filter(k => ti[k] !== undefined && ti[k] !== '').map(k => k + '=' + _cl(ti[k], 60)).join(', ') + ') -> '
      + (o ? [o.status || o.verdict || '', o.reason || ''].filter(Boolean).join(' ') : _cl(s.observation, 60));
  }).join(' | '), 6000);
} catch (e) { toolsLog = '(tools log error: ' + e.message + ')'; }
return [{ json: { output: text.length ? text : fallback, claimProbe: claimProbe, toolsLog } }];

// Get Booker (main v175): who is asking, now from the reference cache instead of a live Airtable read (Tara,
// 29 Sep: staff changes are rare, so up to 15 minutes stale is accepted). Same result as the Airtable search
// {Slack User ID} = "<sender>": the matching Bookers records as {id, fields}, or one empty item when none match.
const user = String($('Slack Trigger').first().json.user || '').trim();
const s = $('Reference Snapshot').first().json;
const rows = (Array.isArray(s.bookers) ? s.bookers : [])
  .filter(r => user && String((r.fields || {})['Slack User ID'] || '').trim() === user);
const out = rows.map(r => ({ json: { id: r.id, fields: r.fields }, pairedItem: { item: 0 } }));
return out.length ? out : [{ json: {}, pairedItem: { item: 0 } }];

